        bool tc = locale == "TC";
        void Check(int tcRva, int scRva, int count, string tcHash, string scHash, string role)
            => VerifyHash(text.AsSpan((tc ? tcRva : scRva) - textRva, count), tc ? tcHash : scHash, role);
